<?php
// api/db.php - PDO SQLite / MySQL Database Connection & Schema Setup

// Load Database Config if present (generated by install.php for Shared Hosting)
$possibleConfigFiles = [
    __DIR__ . '/config.php',
    __DIR__ . '/../data/config.php',
    __DIR__ . '/data/config.php',
    dirname(__DIR__) . '/data/config.php'
];
foreach ($possibleConfigFiles as $cfg) {
    if (file_exists($cfg)) {
        require_once $cfg;
        break;
    }
}

$dbDriver = defined('DB_DRIVER') ? DB_DRIVER : 'sqlite';

$isVercel = getenv('VERCEL') || !empty($_ENV['VERCEL']) || !empty($_SERVER['VERCEL']) ||
            !empty($_ENV['VERCEL_ENV']) || !empty($_SERVER['VERCEL_ENV']) ||
            !empty($_ENV['NOW_REGION']) || !empty($_SERVER['NOW_REGION']) ||
            strpos(__DIR__, '/var/task') !== false || file_exists('/var/task');

try {
    if ($dbDriver === 'mysql') {
        $dbHost = defined('DB_HOST') ? DB_HOST : 'localhost';
        $dbPort = defined('DB_PORT') ? DB_PORT : '3306';
        $dbName = defined('DB_NAME') ? DB_NAME : '';
        $dbUser = defined('DB_USER') ? DB_USER : '';
        $dbPass = defined('DB_PASS') ? DB_PASS : '';

        $dsn = "mysql:host={$dbHost};port={$dbPort};dbname={$dbName};charset=utf8mb4";
        $pdo = new PDO($dsn, $dbUser, $dbPass);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
    } else {
        if ($isVercel) {
            $dbPath = '/tmp/conspodium.db';
            $possibleSeedPaths = [
                __DIR__ . '/conspodium.db',
                __DIR__ . '/../data/conspodium.db',
                __DIR__ . '/data/conspodium.db',
                '/var/task/api/conspodium.db',
                '/var/task/data/conspodium.db',
                '/var/task/conspodium.db',
                dirname(__DIR__) . '/data/conspodium.db'
            ];
            $bestSeed = null;
            foreach ($possibleSeedPaths as $candidate) {
                if (file_exists($candidate) && @filesize($candidate) > 10000) {
                    $bestSeed = $candidate;
                    break;
                }
            }
            if ($bestSeed) {
                $needCopy = !file_exists($dbPath) ||
                            @filesize($dbPath) < @filesize($bestSeed) ||
                            @filemtime($bestSeed) > @filemtime($dbPath);
                if ($needCopy) {
                    @copy($bestSeed, $dbPath);
                }
            }
        } else {
            $rootDir = __DIR__;
            while ($rootDir !== dirname($rootDir)) {
                if (file_exists($rootDir . '/package.json') || file_exists($rootDir . '/router.php')) {
                    break;
                }
                $rootDir = dirname($rootDir);
            }
            $dbDir = $rootDir . '/data';
            if (!file_exists($dbDir)) {
                @mkdir($dbDir, 0777, true);
            }
            $dbPath = $dbDir . '/conspodium.db';
        }

        $pdo = new PDO("sqlite:" . $dbPath);
        $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);
        $pdo->setAttribute(PDO::ATTR_DEFAULT_FETCH_MODE, PDO::FETCH_ASSOC);
    }

    // Create tables if not exist
    $pdo->exec("
        CREATE TABLE IF NOT EXISTS categories (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL UNIQUE,
            slug TEXT NOT NULL UNIQUE,
            icon TEXT,
            description TEXT,
            image TEXT
        );

        CREATE TABLE IF NOT EXISTS posts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            slug TEXT NOT NULL UNIQUE,
            eyebrow TEXT,
            excerpt TEXT,
            content TEXT NOT NULL,
            category_id INTEGER,
            author_name TEXT,
            author_avatar TEXT,
            featured_image TEXT,
            reading_time TEXT DEFAULT '5 min read',
            views INTEGER DEFAULT 0,
            is_featured INTEGER DEFAULT 0,
            status TEXT DEFAULT 'published',
            published_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL
        );

        CREATE TABLE IF NOT EXISTS transcripts (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            post_id INTEGER NOT NULL UNIQUE,
            speaker_name TEXT,
            speaker_title TEXT,
            audio_duration TEXT,
            transcript_content TEXT NOT NULL,
            FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS polls (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            question TEXT NOT NULL,
            options_json TEXT NOT NULL,
            is_active INTEGER DEFAULT 0,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        );

        CREATE TABLE IF NOT EXISTS poll_votes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            poll_id INTEGER NOT NULL,
            option_index INTEGER NOT NULL,
            voter_ip TEXT NOT NULL,
            voted_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (poll_id) REFERENCES polls(id) ON DELETE CASCADE
        );

        CREATE TABLE IF NOT EXISTS story_submissions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            author_name TEXT NOT NULL,
            author_email TEXT NOT NULL,
            author_bio TEXT,
            category TEXT,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            attachment_url TEXT,
            status TEXT DEFAULT 'pending',
            submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP
