        $stmtSub->execute(['Dr. Kemi Adebayo', 'kemi.adebayo@diasporahealth.org', 'Public Health Researcher & Epidemiologist', 'Community', 'Building Resilient Community Health Networks Across West Africa', 'Community health initiatives in Lagos and Accra demonstrate how local knowledge combined with diaspora support can reduce maternal mortality.', '/uploads/health_diaspora_hero.png', 'pending', date('Y-m-d H:i:s', strtotime('-1 days'))]);
